1	#!/usr/bin/env node
2	// stockroom —— 本地多仓库存台账（Node.js 24，TypeScript，无外部运行依赖）
3	
4	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
5	import { join } from 'node:path';
6	
7	const APP_NAME = 'stockroom';
8	const DATA_FILENAME = 'stockroom.json';
9	const DEFAULT_DATA_DIR = '.stockroom';
10	
11	class UsageError extends Error {} // 命令行用法错误 -> 退出码 2
12	class BizError extends Error {} // 业务拒绝 -> 退出码 1
13	class DataError extends Error {} // 数据读取/保存失败 -> 退出码 1
14	
15	type DocType = 'in' | 'out' | 'transfer';
16	type EntryType = DocType | 'count' | 'in-rev' | 'out-rev' | 'transfer-rev' | 'count-rev';
17	
18	interface LedgerEntry {
19	  seq: number; // 全局流水序号，即提交顺序
20	  doc: string; // 单据编号（冲销流水此处为冲销单编号）
21	  type: EntryType;
22	  product: string;
23	  wh: string; // 本流水条目变动余量的仓库
24	  qty?: number; // 入库/出库/调拨类流水：恒为正数，方向由类型 / 出入仓决定；盘点类流水不用此字段
25	  before: number;
26	  after: number;
27	  from?: string; // 调拨（或冲销调拨）的调出仓
28	  to?: string; // 调拨（或冲销调拨）的调入仓
29	  orig?: string; // 冲销流水：被冲销的原单编号
30	  expected?: number; // 盘点（及冲销盘点）流水：预期账面量
31	  actual?: number; // 盘点（及冲销盘点）流水：实盘量
32	  diff?: number; // 盘点差额 = 实盘 - 账面（可正、可负、可零）；冲销盘点流水记录原差额
33	}
34	
35	interface DocRecord {
36	  content: Record<string, unknown>; // 规范化业务内容（明细顺序无关）
37	  resultLines: string[]; // 原提交结果，供幂等重放
38	}
39	
40	interface ReversalRecord {
41	  orig: string; // 被冲销的原单编号
42	  resultLines: string[]; // 冲销提交结果，供幂等重放
43	}
44	
45	interface Store {
46	  version: 1;
47	  products: Record<string, string>; // 编号 -> 名称（编号区分大小写；null 原型，防特殊键串改）
48	  stock: Record<string, Record<string, number>>; // 商品 -> 仓库 -> 余量
49	  entries: LedgerEntry[];
50	  docs: Record<string, DocRecord>; // 入库/出库/调拨单去重与结果
51	  reversals: Record<string, ReversalRecord>; // 冲销单去重与结果
52	}
53	
54	function nullProto<T extends object>(): T {
55	  return Object.create(null) as T;
56	}
57	
58	function emptyStore(): Store {
59	  return {
60	    version: 1,
61	    products: nullProto(),
62	    stock: nullProto(),
63	    entries: [],
64	    docs: nullProto(),
65	    reversals: nullProto(),
66	  };
67	}
68	
69	// ---------- 工具 ----------
70	
71	function isPlainObject(v: unknown): v is Record<string, unknown> {
72	  return typeof v === 'object' && v !== null && !Array.isArray(v);
73	}
74	
75	function isNonNegSafeInt(v: unknown): v is number {
76	  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
77	}
78	
79	function isPosSafeInt(v: unknown): v is number {
80	  return typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
81	}
82	
83	function trimOrThrow(label: string, raw: string): string {
84	  const s = raw.trim();
85	  if (s === '') throw new BizError(`${label}去除首尾空白后不能为空`);
86	  return s;
87	}
88	
89	/** 规范化序列化：对象键排序，保证业务内容比较与明细顺序无关。 */
90	function stableStringify(v: unknown): string {
91	  if (isPlainObject(v)) {
92	    return (
93	      '{' +
94	      Object.keys(v)
95	        .sort()
96	        .map((k) => JSON.stringify(k) + ':' + stableStringify(v[k]))
97	        .join(',') +
98	      '}'
99	    );
100	  }
101	  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
102	  return JSON.stringify(v);
103	}
104	
105	// ---------- 数据持久化 ----------
106	
107	function dataPath(dataDir: string): string {
108	  return join(dataDir, DATA_FILENAME);
109	}
110	
111	function loadStore(dataDir: string): Store {
112	  let raw: string;
113	  try {
114	    raw = readFileSync(dataPath(dataDir), 'utf8');
115	  } catch (e) {
116	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore(); // 尚不存在 -> 空库
117	    throw new DataError(`无法读取数据文件 ${dataPath(dataDir)}：${(e as Error).message}`);
118	  }
119	
120	  let data: unknown;
121	  try {
122	    // JSON.parse 将 "__proto__" 保留为普通自有属性（不设置原型）；随后 validateStore
123	    // 会把全部容器重新装入 null 原型对象，constructor 等特殊键同样安全。
124	    data = JSON.parse(raw);
125	  } catch {
126	    throw new DataError(`数据文件已损坏，无法解析 JSON：${dataPath(dataDir)}（不会作为空库覆盖）`);
127	  }
128	  return validateStore(data);
129	}
130	
131	function validateStore(data: unknown): Store {
132	  const bad = (msg: string): DataError =>
133	    new DataError(`数据文件已损坏或格式不正确（${msg}），拒绝启动以免覆盖原数据`);
134	
135	  if (!isPlainObject(data)) throw bad('根节点不是对象');
136	  if (data.version !== 1) throw bad(`不支持的数据版本：${String(data.version)}`);
137	
138	  // 重新装入 null 原型容器：即使磁盘数据来自普通对象，constructor/__proto__ 等键也安全
139	  const store = emptyStore();
140	
141	  if (!isPlainObject(data.products)) throw bad('products 不是对象');
142	  for (const [id, name] of Object.entries(data.products)) {
143	    if (typeof id !== 'string' || id.trim() === '' || typeof name !== 'string')
144	      throw bad('products 中存在非法编号或名称');
145	    store.products[id] = name;
146	  }
147	
148	  if (!isPlainObject(data.stock)) throw bad('stock 不是对象');
149	  for (const [pid, whs] of Object.entries(data.stock)) {
150	    if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的库存不是对象`);
151	    const whMap = nullProto<Record<string, number>>();
152	    for (const [wh, qty] of Object.entries(whs)) {
153	      if (typeof wh !== 'string' || wh.trim() === '' || !isNonNegSafeInt(qty))
154	        throw bad(`商品 ${pid} 仓库 ${String(wh)} 的余量非法`);
155	      whMap[wh] = qty;
156	    }
157	    store.stock[pid] = whMap;
158	  }
159	
160	  if (!Array.isArray(data.entries)) throw bad('entries 不是数组');
161	  let lastSeq = 0;
162	  for (const e of data.entries as unknown[]) {
163	    if (!isPlainObject(e)) throw bad('存在非法流水条目');
164	    if (!isPosSafeInt(e.seq) || e.seq !== ++lastSeq) throw bad('流水序号不连续');
165	    if (typeof e.doc !== 'string' || e.doc.trim() === '') throw bad('流水缺少单据编号');
166	    const isRev =
167	      e.type === 'in-rev' || e.type === 'out-rev' || e.type === 'transfer-rev' || e.type === 'count-rev';
168	    const isOrig = e.type === 'in' || e.type === 'out' || e.type === 'transfer' || e.type === 'count';
169	    if (!isRev && !isOrig) throw bad('流水类型非法');
170	    if (typeof e.product !== 'string' || e.product.trim() === '') throw bad('流水缺少商品编号');
171	    if (typeof e.wh !== 'string' || e.wh.trim() === '') throw bad('流水缺少仓库标识');
172	    if (!isNonNegSafeInt(e.before) || !isNonNegSafeInt(e.after)) throw bad('流水余量非法');
173	    if (e.type === 'count' || e.type === 'count-rev') {
174	      if (!isNonNegSafeInt(e.expected) || !isNonNegSafeInt(e.actual))
175	        throw bad('盘点流水账面/实盘量非法');
176	      if (typeof e.diff !== 'number' || !Number.isSafeInteger(e.diff)) throw bad('盘点流水差额非法');
177	      if (e.diff !== e.actual - e.expected) throw bad('盘点流水差额与账面、实盘量不一致');
178	      const applied = e.type === 'count' ? e.diff : -e.diff; // 冲销盘点应用反向差额
179	      if (e.after - e.before !== applied) throw bad('盘点流水差额与前后余量不一致');
180	      if (e.qty !== undefined || e.from !== undefined || e.to !== undefined)
181	        throw bad('盘点流水不应携带数量或调拨字段');
182	    } else {
183	      if (!isPosSafeInt(e.qty)) throw bad('流水数量非法');
184	      if (e.expected !== undefined || e.actual !== undefined || e.diff !== undefined)
185	        throw bad('非盘点流水不应携带盘点字段');
186	      const delta = e.after - e.before;
187	      if (e.type === 'transfer' || e.type === 'transfer-rev') {
188	        if (typeof e.from !== 'string' || e.from.trim() === '' || typeof e.to !== 'string' || e.to.trim() === '')
189	          throw bad('调拨流水缺少调出/调入仓');
190	        // 调拨：调入仓增加；冲销调拨：原调入仓扣回、原调出仓补回
191	        const expect = (e.wh === e.to) === (e.type === 'transfer') ? e.qty : -e.qty;
192	        if (delta !== expect) throw bad('流水差额与前后余量不一致');
193	      } else {
194	        const increases = e.type === 'in' || e.type === 'out-rev';
195	        if (delta !== (increases ? e.qty : -e.qty)) throw bad('流水差额与前后余量不一致');
196	      }
197	    }
198	    if (isRev) {
199	      if (typeof e.orig !== 'string' || e.orig.trim() === '') throw bad('冲销流水缺少原单编号');
200	    } else if (e.orig !== undefined) {
201	      throw bad('原始单据流水不应携带冲销标记');
202	    }
203	    store.entries.push(e as unknown as LedgerEntry);
204	  }
205	
206	  if (!isPlainObject(data.docs)) throw bad('docs 不是对象');
207	  for (const [docId, rec] of Object.entries(data.docs)) {
208	    if (typeof docId !== 'string' || docId.trim() === '') throw bad('存在非法单据编号');
209	    if (!isPlainObject(rec) || !isPlainObject(rec.content) || !Array.isArray(rec.resultLines))
210	      throw bad(`单据 ${docId} 的去重记录非法`);
211	    if (!rec.resultLines.every((l) => typeof l === 'string')) throw bad(`单据 ${docId} 的结果记录非法`);
212	    const c = rec.content;
213	    if (c.type !== 'in' && c.type !== 'out' && c.type !== 'transfer' && c.type !== 'count')
214	      throw bad(`单据 ${docId} 的业务类型非法`);
215	    if (!isPlainObject(c.items)) throw bad(`单据 ${docId} 的明细非法`);
216	    for (const [pid, item] of Object.entries(c.items)) {
217	      if (pid.trim() === '') throw bad(`单据 ${docId} 存在非法明细`);
218	      if (c.type === 'count') {
219	        if (!isPlainObject(item) || !isNonNegSafeInt(item.expected) || !isNonNegSafeInt(item.actual))
220	          throw bad(`单据 ${docId} 存在非法盘点明细`);
221	      } else if (!isPosSafeInt(item)) {
222	        throw bad(`单据 ${docId} 存在非法明细`);
223	      }
224	    }
225	    if (c.type === 'transfer') {
226	      if (typeof c.from !== 'string' || c.from.trim() === '' || typeof c.to !== 'string' || c.to.trim() === '')
227	        throw bad(`单据 ${docId} 的调拨仓非法`);
228	    } else if (typeof c.wh !== 'string' || c.wh.trim() === '') {
229	      throw bad(`单据 ${docId} 的仓库非法`);
230	    }
231	    store.docs[docId] = rec as unknown as DocRecord;
232	  }
233	
234	  // reversals 为新增字段：合法旧数据没有该字段，按空集合处理
235	  if (data.reversals !== undefined) {
236	    if (!isPlainObject(data.reversals)) throw bad('reversals 不是对象');
237	    for (const [revId, rec] of Object.entries(data.reversals)) {
238	      if (typeof revId !== 'string' || revId.trim() === '') throw bad('存在非法冲销单编号');
239	      if (!isPlainObject(rec) || typeof rec.orig !== 'string' || rec.orig.trim() === '' ||
240	          !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string'))
241	        throw bad(`冲销单 ${revId} 的记录非法`);
242	      const origRec = store.docs[rec.orig];
243	      if (origRec === undefined) throw bad(`冲销单 ${revId} 指向的原单 ${rec.orig} 不存在`);
244	      if (store.docs[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与原始单据编号冲突`);
245	      store.reversals[revId] = { orig: rec.orig, resultLines: rec.resultLines };
246	    }
247	    // 每张原单最多被成功冲销一次
248	    const origSeen = nullProto<Record<string, string>>();
249	    for (const [revId, rec] of Object.entries(store.reversals)) {
250	      if (origSeen[rec.orig] !== undefined)
251	        throw bad(`原单 ${rec.orig} 被多张冲销单关联（${origSeen[rec.orig]}、${revId}）`);
252	      origSeen[rec.orig] = revId;
253	    }
254	    // 冲销流水必须能找到所属冲销单
255	    for (const e of store.entries) {
256	      if ((e.type === 'in-rev' || e.type === 'out-rev' || e.type === 'transfer-rev' || e.type === 'count-rev') &&
257	          store.reversals[e.doc] === undefined)
258	        throw bad(`流水引用了不存在的冲销单 ${e.doc}`);
259	    }
260	  }
261	
262	  return store;
263	}
264	
265	function saveStore(dataDir: string, store: Store): void {
266	  const path = dataPath(dataDir);
267	  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.tmp`);
268	  try {
269	    mkdirSync(dataDir, { recursive: true });
270	    writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n', 'utf8');
271	    renameSync(tmp, path);
272	  } catch (e) {
273	    throw new DataError(`保存数据失败，已有数据保持不变：${(e as Error).message}`);
274	  }
275	}
276	
277	// ---------- 参数解析 ----------
278	
279	interface ParsedArgs {
280	  positionals: string[];
281	  flags: Record<string, string>;
282	  multi: Record<string, string[]>;
283	}
284	
285	function parseArgs(
286	  tokens: string[],
287	  singles: string[],
288	  multis: string[] = [],
289	): ParsedArgs {
290	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
291	  const singleSet = new Set(singles);
292	  const multiSet = new Set(multis);
293	
294	  for (let i = 0; i < tokens.length; i++) {
295	    const tok = tokens[i];
296	    if (tok.startsWith('--')) {
297	      let key = tok;
298	      let value: string | undefined;
299	      const eq = tok.indexOf('=');
300	      if (eq >= 0) {
301	        key = tok.slice(0, eq);
302	        value = tok.slice(eq + 1);
303	      }
304	      if (!singleSet.has(key) && !multiSet.has(key)) throw new UsageError(`未知参数：${tok}`);
305	      if (value === undefined) {
306	        if (i + 1 >= tokens.length) throw new UsageError(`参数 ${key} 缺少取值`);
307	        value = tokens[++i];
308	      }
309	      if (multiSet.has(key)) (out.multi[key] ??= []).push(value);
310	      else if (out.flags[key] !== undefined) throw new UsageError(`参数 ${key} 重复指定`);
311	      else out.flags[key] = value;
312	    } else {
313	      out.positionals.push(tok);
314	    }
315	  }
316	  return out;
317	}
318	
319	function parseItem(raw: string, merged: Map<string, number>): void {
320	  const idx = raw.indexOf(':');
321	  if (idx <= 0) throw new BizError(`明细格式应为 “商品编号:数量”：${raw}`);
322	  const pid = trimOrThrow('商品编号', raw.slice(0, idx));
323	  const qtyRaw = raw.slice(idx + 1).trim();
324	  if (!/^\d+$/.test(qtyRaw)) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
325	  const qty = Number(qtyRaw);
326	  if (!Number.isSafeInteger(qty) || qty <= 0) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
327	  const sum = (merged.get(pid) ?? 0) + qty; // 同单同商品先合并
328	  if (!Number.isSafeInteger(sum)) throw new BizError(`商品 ${pid} 累计数量超出安全整数范围`);
329	  merged.set(pid, sum);
330	}
331	
332	interface DocRequest {
333	  type: DocType;
334	  docId: string;
335	  wh?: string;
336	  from?: string;
337	  to?: string;
338	  items: Map<string, number>;
339	}
340	
341	function parseDocArgs(type: DocType, tokens: string[]): DocRequest {
342	  const args = parseArgs(tokens, type === 'transfer' ? ['--from', '--to'] : ['--wh'], ['--item']);
343	  const docId = args.positionals[0];
344	  if (docId === undefined || args.positionals.length !== 1)
345	    throw new UsageError(`用法：单据命令需要且仅需要一个单据编号`);
346	
347	  const items = new Map<string, number>();
348	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
349	  if (items.size === 0) throw new UsageError('单据至少需要一条 --item 商品编号:数量 明细');
350	
351	  const req: DocRequest = { type, docId: trimOrThrow('单据编号', docId), items };
352	  if (type === 'transfer') {
353	    if (args.flags['--from'] === undefined || args.flags['--to'] === undefined)
354	      throw new UsageError('调拨单必须提供 --from <调出仓> 与 --to <调入仓>');
355	    req.from = trimOrThrow('调出仓标识', args.flags['--from']);
356	    req.to = trimOrThrow('调入仓标识', args.flags['--to']);
357	    if (req.from === req.to) throw new BizError('调拨单的调出仓与调入仓不能相同');
358	  } else {
359	    if (args.flags['--wh'] === undefined) throw new UsageError('入库/出库单必须提供 --wh <仓库>');
360	    req.wh = trimOrThrow('仓库标识', args.flags['--wh']);
361	  }
362	  return req;
363	}
364	
365	interface CountItem {
366	  expected: number; // 预期账面量
367	  actual: number; // 实盘量
368	}
369	
370	interface CountRequest {
371	  docId: string;
372	  wh: string;
373	  items: Map<string, CountItem>;
374	}
375	
376	function parseNonNegInt(label: string, raw: string): number {
377	  const s = raw.trim();
378	  if (!/^\d+$/.test(s)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
379	  const n = Number(s);
380	  if (!Number.isSafeInteger(n)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
381	  return n;
382	}
383	
384	function parseCountArgs(tokens: string[]): CountRequest {
385	  const args = parseArgs(tokens, ['--wh'], ['--item']);
386	  const docId = args.positionals[0];
387	  if (docId === undefined || args.positionals.length !== 1)
388	    throw new UsageError('用法：count <单据编号> --wh <仓库> --item <商品编号:预期账面量:实盘量> [...]');
389	  if (args.flags['--wh'] === undefined) throw new UsageError('盘点单必须提供 --wh <仓库>');
390	
391	  const items = new Map<string, CountItem>();
392	  for (const raw of args.multi['--item'] ?? []) {
393	    const parts = raw.split(':');
394	    if (parts.length !== 3)
395	      throw new BizError(`盘点明细格式应为 “商品编号:预期账面量:实盘量”：${raw}`);
396	    const pid = trimOrThrow('商品编号', parts[0]);
397	    const expected = parseNonNegInt(`商品 ${pid} 的预期账面量`, parts[1]);
398	    const actual = parseNonNegInt(`商品 ${pid} 的实盘量`, parts[2]);
399	    if (items.has(pid)) throw new BizError(`盘点单中商品 ${pid} 重复出现，拒绝提交`);
400	    items.set(pid, { expected, actual });
401	  }
402	  if (items.size === 0)
403	    throw new UsageError('盘点单至少需要一条 --item 商品编号:预期账面量:实盘量 明细');
404	
405	  return { docId: trimOrThrow('单据编号', docId), wh: trimOrThrow('仓库标识', args.flags['--wh']), items };
406	}
407	
408	// ---------- 业务核心 ----------
409	
410	const MAX_SAFE = Number.MAX_SAFE_INTEGER;
411	
412	/** 带符号数量文本：正数加 +，负数保留 -，零为 0。 */
413	function fmtSigned(n: number): string {
414	  return n > 0 ? `+${n}` : String(n);
415	}
416	
417	function canonicalContent(req: DocRequest): Record<string, unknown> {
418	  const items: Record<string, number> = nullProto();
419	  for (const pid of [...req.items.keys()].sort()) items[pid] = req.items.get(pid)!;
420	  if (req.type === 'transfer') return { type: req.type, from: req.from!, to: req.to!, items };
421	  return { type: req.type, wh: req.wh!, items };
422	}
423	
424	function getStock(stock: Store['stock'], pid: string, wh: string): number {
425	  return stock[pid]?.[wh] ?? 0;
426	}
427	
428	function setStock(stock: Store['stock'], pid: string, wh: string, qty: number): void {
429	  (stock[pid] ??= nullProto<Record<string, number>>())[wh] = qty;
430	}
