432	/**
433	 * 深拷贝余量草稿。必须自建 null 原型容器：structuredClone 不保留 null 原型，
434	 * 普通对象在 "__proto__"/"constructor" 等商品或仓库键下会发生原型串改。
435	 */
436	function cloneStock(stock: Store['stock']): Store['stock'] {
437	  const out = nullProto<Store['stock']>();
438	  for (const pid of Object.keys(stock)) {
439	    const whMap = nullProto<Record<string, number>>();
440	    for (const wh of Object.keys(stock[pid])) whMap[wh] = stock[pid][wh];
441	    out[pid] = whMap;
442	  }
443	  return out;
444	}
