451	/** 整单先校验、模拟，全部合法后才一次性落库；任一明细失败则全部保持原状。 */
452	function submitDocument(dataDir: string, store: Store, req: DocRequest): SubmitOutcome {
453	  const content = canonicalContent(req);
454	  const existed = store.docs[req.docId];
455	  if (existed !== undefined) {
456	    if (stableStringify(existed.content) !== stableStringify(content))
457	      throw new BizError(`单据编号 ${req.docId} 已用于业务内容不同的单据，拒绝提交`);
458	    return { duplicate: true, lines: existed.resultLines }; // 幂等：返回原结果，不动库存
459	  }
460	  // 编号空间与出库/入库/调拨/冲销单共用
461	  if (store.reversals[req.docId] !== undefined)
462	    throw new BizError(`单据编号 ${req.docId} 已用于冲销单，拒绝提交`);
463	
464	  for (const pid of req.items.keys()) {
465	    if (store.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
466	  }
467	
468	  const draft: Store['stock'] = cloneStock(store.stock);
469	  const additions: LedgerEntry[] = [];
470	  const reportLines: string[] = [];
471	  let seq = store.entries.length;
472	  const typeLabel = req.type === 'in' ? '入库' : req.type === 'out' ? '出库' : '调拨';
473	
474	  for (const pid of [...req.items.keys()].sort()) {
475	    const qty = req.items.get(pid)!;
476	
477	    if (req.type === 'in') {
478	      const wh = req.wh!;
479	      const before = getStock(draft, pid, wh);
480	      const after = before + qty;
481	      if (after > MAX_SAFE) throw new BizError(`商品 ${pid} 入库后余量超出安全整数范围，拒绝整单`);
482	      setStock(draft, pid, wh, after);
483	      additions.push({ seq: ++seq, doc: req.docId, type: 'in', product: pid, wh, qty, before, after });
484	      reportLines.push(`入库 ${pid} @${wh} +${qty}：${before} -> ${after}`);
485	    } else if (req.type === 'out') {
486	      const wh = req.wh!;
487	      const before = getStock(draft, pid, wh);
488	      if (before < qty)
489	        throw new BizError(`商品 ${pid} 仓库 ${wh} 余量不足（当前 ${before}，需出库 ${qty}），拒绝整单`);
490	      const after = before - qty;
491	      setStock(draft, pid, wh, after);
492	      additions.push({ seq: ++seq, doc: req.docId, type: 'out', product: pid, wh, qty, before, after });
493	      reportLines.push(`出库 ${pid} @${wh} -${qty}：${before} -> ${after}`);
494	    } else {
495	      const from = req.from!;
496	      const to = req.to!;
497	      const beforeFrom = getStock(draft, pid, from);
498	      if (beforeFrom < qty)
499	        throw new BizError(`商品 ${pid} 调出仓 ${from} 余量不足（当前 ${beforeFrom}，需调拨 ${qty}），拒绝整单`);
500	      const afterFrom = beforeFrom - qty;
501	      const beforeTo = getStock(draft, pid, to);
502	      const afterTo = beforeTo + qty;
503	      if (afterTo > MAX_SAFE) throw new BizError(`商品 ${pid} 调入后余量超出安全整数范围，拒绝整单`);
504	      setStock(draft, pid, from, afterFrom);
505	      setStock(draft, pid, to, afterTo);
506	      additions.push({
507	        seq: ++seq, doc: req.docId, type: 'transfer', product: pid, wh: from,
508	        qty, before: beforeFrom, after: afterFrom, from, to,
509	      });
510	      additions.push({
511	        seq: ++seq, doc: req.docId, type: 'transfer', product: pid, wh: to,
512	        qty, before: beforeTo, after: afterTo, from, to,
513	      });
514	      reportLines.push(
515	        `调拨 ${pid} ${from} -> ${to} ${qty}：${from} ${beforeFrom}->${afterFrom}；${to} ${beforeTo}->${afterTo}`,
516	      );
517	    }
518	  }
519	
520	  // 全部明细合法：一次性提交并在保存成功后才算成功
521	  store.stock = draft;
522	  store.entries.push(...additions);
523	  store.docs[req.docId] = { content, resultLines: reportLines };
524	  saveStore(dataDir, store);
525	
526	  return {
527	    duplicate: false,
528	    lines: [`${typeLabel}单 ${req.docId} 提交成功，共 ${req.items.size} 种商品：`, ...reportLines],
529	  };
530	}
