532	function canonicalCountContent(req: CountRequest): Record<string, unknown> {
533	  const items: Record<string, unknown> = nullProto();
534	  for (const pid of [...req.items.keys()].sort()) {
535	    const it = req.items.get(pid)!;
536	    items[pid] = { expected: it.expected, actual: it.actual };
537	  }
538	  return { type: 'count', wh: req.wh, items };
539	}
