812	const TYPE_LABEL: Record<EntryType, string> = {
813	  in: '入库',
814	  out: '出库',
815	  transfer: '调拨',
816	  count: '盘点',
817	  'in-rev': '冲销入库',
818	  'out-rev': '冲销出库',
819	  'transfer-rev': '冲销调拨',
820	  'count-rev': '冲销盘点',
821	};
822	
823	function formatEntry(e: LedgerEntry): string {
824	  let line: string;
825	  if (e.type === 'count' || e.type === 'count-rev') {
826	    const applied = e.type === 'count' ? e.diff! : -e.diff!; // 冲销盘点应用反向差额
827	    line =
828	      `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}` +
829	      `\t差额=${fmtSigned(applied)}\t${e.before}->${e.after}\t账面=${e.expected}\t实盘=${e.actual}`;
830	  } else {
831	    let signed: string;
832	    // 符号必须与前后余量一致：入库/冲销出库/调入方向为增，其余为减
833	    const increases =
834	      e.type === 'in' || e.type === 'out-rev' ||
835	      ((e.type === 'transfer' || e.type === 'transfer-rev') &&
836	        (e.type === 'transfer') === (e.wh === e.to));
837	    signed = `${increases ? '+' : '-'}${e.qty}`;
838	    line = `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}\t${signed}\t${e.before}->${e.after}`;
839	    if (e.type === 'transfer' || e.type === 'transfer-rev') line += `\t调拨=${e.from}->${e.to}`;
840	  }
841	  if (e.orig !== undefined) line += `\t原单=${e.orig}`;
842	  return line;
843	}
844	
845	function runFlow(rest: string[], store: Store): void {
846	  const args = parseArgs(rest, ['--product', '--wh']);
847	  if (args.positionals.length > 0) throw new UsageError('用法：flow (--product <商品编号> | --wh <仓库>)…');
848	  const product = args.flags['--product'];
849	  const wh = args.flags['--wh'];
850	  if (product === undefined && wh === undefined)
851	    throw new UsageError('flow 至少需要一个过滤条件：--product <商品编号> 和/或 --wh <仓库>');
852	  const pid = product === undefined ? undefined : trimOrThrow('商品编号', product);
853	  const wid = wh === undefined ? undefined : trimOrThrow('仓库标识', wh);
854	
855	  const rows = store.entries.filter(
856	    (e) => (pid === undefined || e.product === pid) && (wid === undefined || e.wh === wid),
857	  );
858	  const scope = [pid !== undefined ? `商品=${pid}` : null, wid !== undefined ? `仓库=${wid}` : null]
859	    .filter(Boolean)
860	    .join(' ');
861	  console.log(`流水（${scope}），共 ${rows.length} 条，按提交顺序（冲销流水标注原单编号）：`);
862	  if (rows.length === 0) console.log('（无匹配流水）');
863	  else for (const e of rows) console.log(formatEntry(e));
864	
865	  // 附：范围内原始单据的冲销状态
866	  const origDocs = new Set(rows.filter((e) => e.orig === undefined).map((e) => e.doc));
867	  const status: string[] = [];
868	  for (const docId of [...origDocs].sort()) {
869	    for (const [revId, rec] of Object.entries(store.reversals)) {
870	      if (rec.orig === docId) status.push(`原单 ${docId} 已由冲销单 ${revId} 冲销`);
871	    }
872	  }
873	  for (const line of status) console.log(line);
874	}
875	
876	function runReverse(rest: string[], dataDir: string, store: Store): void {
877	  const args = parseArgs(rest, ['--orig']);
878	  const revRaw = args.positionals[0];
879	  if (revRaw === undefined || args.positionals.length !== 1)
880	    throw new UsageError('用法：reverse <冲销单编号> --orig <原单编号>');
881	  if (args.flags['--orig'] === undefined)
882	    throw new UsageError('冲销必须通过 --orig <原单编号> 指定被冲销的原单');
883	  const revId = trimOrThrow('冲销单编号', revRaw);
884	  const origId = trimOrThrow('原单编号', args.flags['--orig']);
885	  const outcome = submitReversal(dataDir, store, revId, origId);
886	  if (outcome.duplicate) {
887	    console.log(
888	      `冲销单 ${revId} 为重复提交，原单为 ${origId}，返回原冲销结果（库存与流水不再变动）：`,
889	    );
890	  }
891	  for (const line of outcome.lines) console.log(line);
892	}
893	
894	// ---------- 帮助与入口 ----------
895	
896	const HELP = `${APP_NAME} —— 本地多仓库存台账
897	
898	用法：
899	  node app.ts [-d, --data <数据目录>] <命令> [参数]
900	
901	全局选项：
902	  -d, --data <目录>   数据目录（默认 ./.stockroom）；不同目录的数据互不影响
903	
904	命令：
905	  product add <编号> <名称>                 登记商品（编号唯一、区分大小写，去空白后不能为空）
906	  product list                              列出已登记商品
907	  in <单据编号> --wh <仓库> --item <编号:数量> [...]       入库
908	  out <单据编号> --wh <仓库> --item <编号:数量> [...]      出库（余量不足整单拒绝）
909	  transfer <单据编号> --from <源仓> --to <目标仓> \\
910	           --item <编号:数量> [...]                        跨仓调拨（两仓不能相同）
911	  count <单据编号> --wh <仓库> \\
912	        --item <编号:预期账面量:实盘量> [...]              整单盘点校正（先核对账面再按实盘校正）
913	  reverse <冲销单编号> --orig <原单编号>     整单冲销已成功的入库/出库/调拨/盘点单
914	  balance <商品编号> [--wh <仓库>]           查询余量；省略 --wh 查询各仓
915	  flow --product <编号> [--wh <仓库>]        按商品/仓库查询流水（至少一个过滤条件）
916	       | --wh <仓库> [--product <编号>]
917	  -h, --help                                显示本帮助
918	
919	规则：
920	  数量必须为正安全整数；同单同商品的重复明细先合并，再做足量与溢出校验；
921	  任一明细不合法则整单拒绝。单据编号（含冲销单）在同一数据目录内共用全局唯一
922	  编号空间，相同内容重复提交返回原结果且不重复变动，同编号不同内容拒绝；失败
923	  提交不占用编号。
924	
925	盘点规则：
926	  盘点单逐项给出某仓库中已登记商品的预期账面量与实盘量（均为非负安全整数），
927	  同商品重复出现拒绝。首次提交先逐项核对当前余量与预期账面量，任一不符整单
928	  拒绝并说明冲突商品及当前量；全部相符才把列出的商品校正为实盘量（差额 =
929	  实盘 - 账面，可增、可减、可为零；全零差额仍记为成功单据并逐项追加流水），
930	  未列出的商品及其他仓库不变。同编号同内容重放只返回原结果，即使余量改变或
931	  盘点已冲销也不再核对、不再生效；同编号不同内容或其他业务拒绝。
932	
933	冲销规则：
934	  冲销在“当前余量”上应用原单的相反变动，不回滚原单之后的其他业务、不恢复绝对
935	  余量：冲销入库从原目标仓扣回；冲销出库向原来源仓补回；冲销调拨从原调入仓扣
936	  回并向原调出仓补回；冲销盘点在当前余量上减去原盘点差额（零差额不改余量，
937	  但仍记录冲销关系与流水）。数量取原单合并后的明细。任一商品扣回不足、补回后
938	  溢出或冲减后为负则整单拒绝、不占用冲销单编号、原单不标记冲销，条件改善后
939	  可重试。
940	  只能冲销成功的原始单据；原单不存在、冲销单本身、已冲销过的原单均不能再次冲
941	  销，每张原单最多冲销一次。冲销成功后重放原单仍只返回其最初结果，不会重新生
942	  效；重放冲销单返回原冲销结果，不再变动，同编号改指其他原单则拒绝。
943	
944	示例：
945	  node app.ts -d ./data product add P1 螺丝
946	  node app.ts -d ./data in D1 --wh W1 --item P1:10 --item P2:3
947	  node app.ts -d ./data out D2 --wh W1 --item P1:4
948	  node app.ts -d ./data transfer D3 --from W1 --to W2 --item P1:2 --item P1:3
949	  node app.ts -d ./data count C1 --wh W1 --item P1:1:5 --item P2:3:3
950	  node app.ts -d ./data reverse R1 --orig D3
951	  node app.ts -d ./data reverse R2 --orig C1
952	  node app.ts -d ./data balance P1
953	  node app.ts -d ./data balance P1 --wh W1
954	  node app.ts -d ./data flow --product P1
955	  node app.ts -d ./data flow --wh W2`;
956	
957	function printHelp(): void {
958	  console.log(HELP);
959	}
960	
961	function run(argv: string[]): void {
962	  // 先抽出全局 -d/--data，其余按命令解析
963	  let dataDir = DEFAULT_DATA_DIR;
964	  const rest: string[] = [];
965	  for (let i = 0; i < argv.length; i++) {
966	    const t = argv[i];
967	    if (t === '-d' || t === '--data') {
968	      if (i + 1 >= argv.length) throw new UsageError(`参数 ${t} 缺少数据目录取值`);
969	      dataDir = argv[++i];
970	    } else if (t.startsWith('--data=')) {
971	      dataDir = t.slice('--data='.length);
972	    } else {
973	      rest.push(t);
974	    }
975	  }
976	
977	  if (rest.length === 0) {
978	    printHelp();
979	    return;
980	  }
981	  const cmd = rest[0];
982	  if ((cmd === '-h' || cmd === '--help') && rest.length === 1) {
983	    printHelp();
984	    return;
985	  }
986	
987	  const tokens = rest.slice(1);
988	  switch (cmd) {
989	    case 'product': {
990	      const store = loadStore(dataDir);
991	      runProduct(tokens, dataDir, store);
992	      break;
993	    }
994	    case 'in':
995	    case 'out':
996	    case 'transfer': {
997	      const req = parseDocArgs(cmd, tokens);
998	      const store = loadStore(dataDir);
999	      const outcome = submitDocument(dataDir, store, req);
1000	      if (outcome.duplicate) {
1001	        console.log(`单据 ${req.docId} 为重复提交，业务内容与原提交一致，返回原提交结果（库存与流水不变）：`);
1002	      }
1003	      for (const line of outcome.lines) console.log(line);
1004	      break;
1005	    }
1006	    case 'count': {
1007	      const req = parseCountArgs(tokens);
1008	      const store = loadStore(dataDir);
1009	      const outcome = submitCount(dataDir, store, req);
1010	      if (outcome.duplicate) {
1011	        console.log(`盘点单 ${req.docId} 为重复提交，业务内容与原提交一致，返回原提交结果（库存与流水不变）：`);
1012	      }
1013	      for (const line of outcome.lines) console.log(line);
1014	      break;
1015	    }
1016	    case 'reverse': {
1017	      const store = loadStore(dataDir);
1018	      runReverse(tokens, dataDir, store);
1019	      break;
1020	    }
1021	    case 'balance': {
1022	      const store = loadStore(dataDir);
1023	      runBalance(tokens, store);
1024	      break;
1025	    }
1026	    case 'flow': {
1027	      const store = loadStore(dataDir);
1028	      runFlow(tokens, store);
1029	      break;
1030	    }
1031	    default:
1032	      throw new UsageError(`未知命令：${cmd}（使用 --help 查看可用命令）`);
1033	  }
1034	}
1035	
1036	try {
1037	  run(process.argv.slice(2));
1038	} catch (e) {
1039	  if (e instanceof UsageError) {
1040	    console.error(`${APP_NAME}: ${e.message}`);
1041	    process.exit(2);
1042	  }
1043	  if (e instanceof BizError || e instanceof DataError) {
1044	    console.error(`${APP_NAME}: ${e.message}`);
1045	    process.exit(1);
1046	  }
1047	  console.error(`${APP_NAME}: 发生未预期错误：${(e as Error)?.stack ?? String(e)}`);
1048	  process.exit(1);
1049	}
